import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"NodeLoc 身份、等级与本站配额","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodeloc-identity.md","filePath":"guide/nodeloc-identity.md","lastUpdated":0}`),a={name:`guide/nodeloc-identity.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="nodeloc-身份、等级与本站配额" tabindex="-1">NodeLoc 身份、等级与本站配额 <a class="header-anchor" href="#nodeloc-身份、等级与本站配额" aria-label="Permalink to “NodeLoc 身份、等级与本站配额”">​</a></h1><p>草丛 Mail 分别记录账号的<strong>注册来源</strong>、已经绑定的<strong>外部身份</strong>、NodeLoc 返回的<strong>真实会员等级</strong>，以及本站实际使用的<strong>系统配额等级</strong>。这四项含义不同，界面不会再用本站配额反推 NodeLoc 会员等级。</p><h2 id="界面会怎样显示" tabindex="-1">界面会怎样显示 <a class="header-anchor" href="#界面会怎样显示" aria-label="Permalink to “界面会怎样显示”">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>注册来源</th><th>NodeLoc 实际等级</th><th>系统配额等级</th></tr></thead><tbody><tr><td>邮箱表单注册，未绑定 NodeLoc</td><td>普通账号</td><td>不显示</td><td><code>L0</code>–<code>L4</code> 中当前生效档位</td></tr><tr><td>邮箱表单注册，后来绑定 NodeLoc</td><td>普通账号</td><td>NodeLoc 返回的真实 <code>TL0</code>–<code>TL4</code></td><td>按后台映射换算后的 <code>L0</code>–<code>L4</code></td></tr><tr><td>首次通过 NodeLoc 登录创建账号</td><td>NodeLoc 账号</td><td>NodeLoc 返回的真实 <code>TL0</code>–<code>TL4</code></td><td>按后台映射换算后的 <code>L0</code>–<code>L4</code></td></tr><tr><td>已绑定，但暂时取不到等级</td><td>普通账号或 NodeLoc 账号</td><td>等级待同步</td><td>保留当前本站配额档位</td></tr></tbody></table><p>因此，“已绑定 NodeLoc · 黄金会员（TL2）”只会在该绑定实际保存为 <code>TL2</code> 时出现。它不是所有 NodeLoc 绑定的统一文案。真实等级对应关系如下：</p><table tabindex="0"><thead><tr><th>NodeLoc 代码</th><th>显示名称</th></tr></thead><tbody><tr><td><code>TL0</code></td><td>青铜会员</td></tr><tr><td><code>TL1</code></td><td>白银会员</td></tr><tr><td><code>TL2</code></td><td>黄金会员</td></tr><tr><td><code>TL3</code></td><td>钻石会员</td></tr><tr><td><code>TL4</code></td><td>王者会员</td></tr></tbody></table><p>用户页和管理员列表都按每个账号自己的 NodeLoc 绑定读取 <code>oauth_account_bindings.external_level_code</code>。未知或升级前缺失的值显示“等级待同步”，绝不会回退到本站 <code>users.level</code> 猜成某个 NodeLoc 等级。</p><h2 id="普通账号绑定-nodeloc" tabindex="-1">普通账号绑定 NodeLoc <a class="header-anchor" href="#普通账号绑定-nodeloc" aria-label="Permalink to “普通账号绑定 NodeLoc”">​</a></h2><p>在“管理 → 账号设置 → 账号”找到“NodeLoc 账号绑定”。为防止他人利用尚未退出的浏览器会话抢绑账号，开始绑定前需要验证当前密码；已经启用两步验证时也可以使用当前六位 TOTP 验证码。启用 Turnstile 的站点还需要先完成人机验证。</p><p>授权成功后：</p><ul><li>注册来源仍显示“普通账号”，不会伪装成 NodeLoc 注册账号。</li><li>单独显示绑定的 NodeLoc 账号、NodeLoc ID、真实 TL 等级、同步状态和最后同步时间。</li><li>首次绑定立即按照后台映射更新本站系统配额等级。</li><li>以后通过同一个 NodeLoc 授权登录时，可以同步最新等级。</li></ul><p>一个 NodeLoc 身份只能属于一个草丛 Mail 用户；同一用户也不能用另一个 NodeLoc 身份覆盖已有绑定。遇到“已绑定其他账号”时，应先确认实际归属，不要新建同名本地账号绕过。</p><h2 id="重新授权与等级同步" tabindex="-1">重新授权与等级同步 <a class="header-anchor" href="#重新授权与等级同步" aria-label="Permalink to “重新授权与等级同步”">​</a></h2><p>绑定卡片显示“需要重新授权”或“同步失败”时，使用“验证并重新授权 NodeLoc”。重新授权只接受原来绑定的同一个 NodeLoc 身份，用于恢复过期授权或立即刷新等级。</p><p>后台“登录时同步第三方等级”开启后，成功的 NodeLoc 授权登录会刷新真实等级，并按当前映射更新本站配额档位。关闭后，首次绑定仍会应用映射，后续登录不主动改档。</p><p>登录同步会把绑定资料、真实等级和本站配额作为同一笔事务更新；较早开始的后台同步不会覆盖更新的登录结果。页面上的找回邮箱验证状态仍来自草丛 Mail 数据库，不由 NodeLoc 资料猜测。</p><h2 id="最低等级规则" tabindex="-1">最低等级规则 <a class="header-anchor" href="#最低等级规则" aria-label="Permalink to “最低等级规则”">​</a></h2><p>管理员可以设置首次使用 NodeLoc 的最低信任等级。该门槛只用于：</p><ul><li>首次通过 NodeLoc 创建账号。</li><li>普通账号第一次绑定 NodeLoc。</li></ul><p>已经存在或已经绑定的账号不会因为管理员后来提高门槛而被禁止登录。这样可以防止策略调整把老用户锁在门外。</p><p>这个最低等级不限制普通邮箱表单注册；普通注册由“开放注册”和“邮箱验证后才能注册”单独控制。因此后台仍可能同时存在普通账号和低于当前 NodeLoc 门槛的历史账号。</p><h2 id="配额怎样计算" tabindex="-1">配额怎样计算 <a class="header-anchor" href="#配额怎样计算" aria-label="Permalink to “配额怎样计算”">​</a></h2><p>NodeLoc 的 <code>TL0</code>–<code>TL4</code> 会先通过后台映射成本站的 <code>L0</code>–<code>L4</code>。每个 <code>L</code> 档位定义邮箱数量、存储和每日发信基础配额。个人 Pro 套餐可以提供更高权益，管理员也可以对单个用户设置覆盖值。</p><p>查看问题时依次核对：</p><ol><li>账号设置中的 NodeLoc 实际等级。</li><li>管理员后台“第三方等级规则”的 TL 到 L 映射。</li><li>“系统配额等级模板”中对应 L 档位的数值。</li><li>用户是否有个人套餐或管理员覆盖值。</li></ol><p>不要把“系统配额 L2”写成“NodeLoc 黄金会员”。两者可能通过默认映射碰巧对应，也可能被管理员改成完全不同的关系。</p><h2 id="找回邮箱与-nodeloc-登录" tabindex="-1">找回邮箱与 NodeLoc 登录 <a class="header-anchor" href="#找回邮箱与-nodeloc-登录" aria-label="Permalink to “找回邮箱与 NodeLoc 登录”">​</a></h2><p>找回邮箱和 NodeLoc 身份也是两件事。普通账号应在账号设置中绑定并验证找回邮箱，才能自助重置密码。直接由 NodeLoc 登录管理的账号，登录凭据由 NodeLoc 处理；页面会明确显示登录平台来源。</p>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};